package com.bank.transfer.consumer;

import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import lombok.extern.slf4j.Slf4j;
import java.math.BigDecimal;

@Component
@Slf4j
public class DedupSettlementConsumer {

    private final ProcessedTransferRepository processedRepo;
    private final AccountRepository accountRepo;

    public DedupSettlementConsumer(ProcessedTransferRepository p, AccountRepository a) {
        this.processedRepo = p;
        this.accountRepo = a;
    }

    @KafkaListener(topics = "settlements", groupId = "settlement-apply")
    @Transactional
    public void onSettlement(SettlementEvent event, Acknowledgment ack) {
        // APPLICATION-LEVEL dedup using the business idempotency key (transferId).
        if (processedRepo.existsById(event.getTransferId())) {
            log.warn("Duplicate settlement {} ignored (already processed)", event.getTransferId());
            ack.acknowledge();
            return;
        }
        accountRepo.credit(event.getToAccount(), event.getAmount());
        processedRepo.markProcessed(event.getTransferId(), event.getToAccount(), event.getAmount());
        log.info("Applied settlement {} crediting {} amount {}",
                event.getTransferId(), event.getToAccount(), event.getAmount());
        ack.acknowledge();
    }
}
```

