```java
// ─── File: demo/DuplicateDemo.java ───
package com.bank.transfer.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DuplicateDemo {

    private static final Logger log = Logger.getLogger(DuplicateDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        Broker broker = new Broker();
        IdempotentProducer producer = new IdempotentProducer(broker);

        SettlementEvent e = new SettlementEvent("TXF-123", "CUR3001", new BigDecimal("50000"));

        log.info("=== Idempotent producer dedupes its OWN retransmission ===");
        producer.send(e);
        producer.retransmitLast(); // simulate lost-ack retry: SAME batch, same seq
        log.info("Records on broker after client retry = " + broker.recordCount()
                + " (idempotence collapsed the retransmission)");

        log.info("=== But TWO application sends are NOT deduped ===");
        broker.clear();
        producer.resetSession();
        producer.send(e);              // API call 1
        producer.send(e);              // API call 2 (mobile app auto-retried the HTTP request)
        log.severe("Records on broker after two app sends = " + broker.recordCount()
                + " (DUPLICATE settlement — idempotent producer did NOT help)");

        log.info("=== Consumer-side dedup by transferId fixes it ===");
        DedupConsumer consumer = new DedupConsumer();
        BigDecimal credited = BigDecimal.ZERO;
        for (SettlementEvent rec : broker.readAll()) {
            credited = credited.add(consumer.apply(rec, log));
        }
        log.info("Priya net credited = " + credited + " (exactly once, duplicates skipped)");
    }
}

// ─── Would be in SettlementEvent.java in a real project ───
class SettlementEvent {
    private final String transferId;   // the idempotency key
    private final String toAccount;
    private final BigDecimal amount;
    SettlementEvent(String t, String a, BigDecimal amt) { transferId = t; toAccount = a; amount = amt; }
    String getTransferId() { return transferId; }
    String getToAccount() { return toAccount; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in Broker.java in a real project ───
class Broker {
    private final List<SettlementEvent> log = new ArrayList<>();
    void append(SettlementEvent e) { log.add(e); }
    int recordCount() { return log.size(); }
    void clear() { log.clear(); }
    List<SettlementEvent> readAll() { return log; }
}

// ─── Would be in IdempotentProducer.java in a real project ───
class IdempotentProducer {
    private final Broker broker;
    private long producerId = 1;
    private long lastSeq = -1;         // highest sequence accepted this session
    private SettlementEvent lastSent;
    private long lastSentSeq;

    IdempotentProducer(Broker broker) { this.broker = broker; }

    // Each send gets a NEW sequence number — two app sends = two records.
    void send(SettlementEvent e) {
        long seq = ++lastSeq;
        broker.append(e);
        lastSent = e; lastSentSeq = seq;
    }

    // Retransmitting the SAME batch reuses the SAME sequence -> broker discards it.
    void retransmitLast() {
        if (lastSentSeq <= peekBrokerHighestSeq()) {
            // broker already has this seq; idempotence suppresses the duplicate write
            return;
        }
        broker.append(lastSent);
    }

    private long peekBrokerHighestSeq() { return lastSentSeq; } // already persisted

    void resetSession() { producerId++; lastSeq = -1; } // restart => new producer id
}

// ─── Would be in DedupConsumer.java in a real project ───
class DedupConsumer {
    private final Set<String> processed = new HashSet<>(); // durable table in production
    BigDecimal apply(SettlementEvent e, Logger log) {
        if (!processed.add(e.getTransferId())) {
            log.warning("Duplicate " + e.getTransferId() + " skipped");
            return BigDecimal.ZERO;
        }
        log.info("Applied settlement " + e.getTransferId() + " crediting " + e.getToAccount());
        return e.getAmount();
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
